from itertools import product

def solve():
    for n in range(3, 10):
        for k in range(1, n // 2 + 1):
            if n <= 2 * k:
                continue

            # The leader's string is S. The deputy leader writes down X = {x | d_H(x, S) = k}.
            # The contestant sees X. We want to find all S' such that {x | d_H(x, S') = k} = X.
            # Since the problem is symmetric, we can fix S = (0, 0, ..., 0).
            S = (0,) * n
            X = []
            for x in product([0, 1], repeat=n):
                dist = sum(1 for i in range(n) if x[i] != S[i])
                if dist == k:
                    X.append(x)

            X_set = set(X)
            Y = []
            for S_prime in product([0, 1], repeat=n):
                X_prime = []
                for x in product([0, 1], repeat=n):
                    dist = sum(1 for i in range(n) if x[i] != S_prime[i])
                    if dist == k:
                        X_prime.append(x)

                if set(X_prime) == X_set:
                    Y.append(S_prime)

            print(f"n={n}, k={k}, |Y|={len(Y)}")

solve()

import itertools

def solve():
    for n in range(3, 8):
        for k in range(1, n // 2 + 1):
            if n <= 2 * k:
                continue

            strings = list(itertools.product([0, 1], repeat=n))
            # X_S is a set of strings at distance k from S
            X = []
            for s in strings:
                current_X = []
                for x in strings:
                    dist = sum(1 for i in range(n) if x[i] != s[i])
                    if dist == k:
                        current_X.append(x)
                X.append(tuple(sorted(current_X)))

            # Count how many times each set X appears
            counts = {}
            for x_set in X:
                counts[x_set] = counts.get(x_set, 0) + 1

            max_count = max(counts.values())
            print(f"n={n}, k={k}, max_guesses={max_count}")

solve()

